import{_ as s,c as o,o as n,j as i,Y as r,t as a}from"./chunks/framework.D-NV0Bun.js";const f=JSON.parse('{"title":"nsswitch.conf | x-cmd man (man5) | Name Service Switch configuration file","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | nsswitch.conf - Name Service Switch configuration file","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"nsswitch.conf | x-cmd man (man5) | Name Service Switch configuration file"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | nsswitch.conf - Name Service Switch configuration file"}]]},"headers":[],"params":{"isMan":true,"man":"nsswitch.conf","category":"man5","desc":"Name Service Switch configuration file"},"relativePath":"man5/nsswitch.conf.md","filePath":"man5/[man].md"}'),d={name:"man5/nsswitch.conf.md"},l={class:"visually-hidden"};function c(t,e,u,p,h,m){return n(),o("div",null,[i("h1",l,a(t.$params.man),1),e[0]||(e[0]=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>nsswitch.conf - Name Service Switch configuration file</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The Name Service Switch (NSS) configuration file, <em>/etc/nsswitch.conf</em>, is used by the GNU C Library and certain other applications to determine the sources from which to obtain name-service information in a range of categories, and in what order. Each category of information is identified by a database name.</p><p>The file is plain ASCII text, with columns separated by spaces or tab characters. The first column specifies the database name. The remaining columns describe the order of sources to query and a limited set of actions that can be performed by lookup result.</p><p>The following databases are understood by the GNU C Library:</p><dl><dt><strong>aliases</strong></dt><dd>Mail aliases, used by <strong>getaliasent</strong>(3) and related functions.</dd><dt><strong>ethers</strong></dt><dd>Ethernet numbers.</dd><dt><strong>group</strong></dt><dd>Groups of users, used by <strong>getgrent</strong>(3) and related functions.</dd><dt><strong>hosts</strong></dt><dd>Host names and numbers, used by <strong>gethostbyname</strong>(3) and related functions.</dd><dt><strong>initgroups</strong></dt><dd>Supplementary group access list, used by <strong>getgrouplist</strong>(3) function.</dd><dt><strong>netgroup</strong></dt><dd>Network-wide list of hosts and users, used for access rules. C libraries before glibc 2.1 supported netgroups only over NIS.</dd><dt><strong>networks</strong></dt><dd>Network names and numbers, used by <strong>getnetent</strong>(3) and related functions.</dd><dt><strong>passwd</strong></dt><dd>User passwords, used by <strong>getpwent</strong>(3) and related functions.</dd><dt><strong>protocols</strong></dt><dd>Network protocols, used by <strong>getprotoent</strong>(3) and related functions.</dd><dt><strong>publickey</strong></dt><dd>Public and secret keys for Secure_RPC used by NFS and NIS+.</dd><dt><strong>rpc</strong></dt><dd>Remote procedure call names and numbers, used by <strong>getrpcbyname</strong>(3) and related functions.</dd><dt><strong>services</strong></dt><dd>Network services, used by <strong>getservent</strong>(3) and related functions.</dd><dt><strong>shadow</strong></dt><dd>Shadow user passwords, used by <strong>getspnam</strong>(3) and related functions.</dd></dl><p>The GNU C Library ignores databases with unknown names. Some applications use this to implement special handling for their own databases. For example, <strong>sudo</strong>(8) consults the <strong>sudoers</strong> database. Delegation of subordinate user/group IDs can be configured using the <strong>subid</strong> database. Refer to <strong>subuid</strong>(5) and <strong>subgid</strong>(5) for more details.</p><p>Here is an example <em>/etc/nsswitch.conf</em> file:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">passwd:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compat</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">group:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  compat</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compat</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hosts:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  dns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [!UNAVAIL=return] files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">networks:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   nis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [NOTFOUND=return] files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ethers:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [NOTFOUND=return] files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">protocols:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  nis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [NOTFOUND=return] files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rpc:nis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [NOTFOUND=return] files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">services:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   nis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [NOTFOUND=return] files</span></span></code></pre></div><p>The first column is the database name. The remaining columns specify:</p><ul><li><p>One or more service specifications, for example, &quot;files&quot;, &quot;db&quot;, or &quot;nis&quot;. The order of the services on the line determines the order in which those services will be queried, in turn, until a result is found.</p></li><li><p>Optional actions to perform if a particular result is obtained from the preceding service, for example, &quot;[NOTFOUND=return]&quot;.</p></li></ul><p>The service specifications supported on your system depend on the presence of shared libraries, and are therefore extensible. Libraries called <em>/lib/libnss_SERVICE.so.</em>* <em>X</em>* will provide the named <em>SERVICE</em>. On a standard installation, you can use &quot;files&quot;, &quot;db&quot;, &quot;nis&quot;, and &quot;nisplus&quot;. For the <strong>hosts</strong> database, you can additionally specify &quot;dns&quot;. For the <strong>passwd</strong>, <strong>group</strong>, and <strong>shadow</strong> databases, you can additionally specify &quot;compat&quot; (see <strong>Compatibility mode</strong> below). The version number <strong>X</strong> may be 1 for glibc 2.0, or 2 for glibc 2.1 and later. On systems with additional libraries installed, you may have access to further services such as &quot;hesiod&quot;, &quot;ldap&quot;, &quot;winbind&quot;, and &quot;wins&quot;.</p><p>An action may also be specified following a service specification. The action modifies the behavior following a result obtained from the preceding data source. Action items take the general form:</p><blockquote><p>[<em>STATUS</em>=<em>ACTION</em>] <br> &gt; [!<em>STATUS</em>=<em>ACTION</em>]</p></blockquote><p>where</p><blockquote><p><em>STATUS</em> =&gt; <strong>success</strong> | <strong>notfound</strong> | <strong>unavail</strong> | <strong>tryagain</strong> <br> &gt; <em>ACTION</em> =&gt; <strong>return</strong> | <strong>continue</strong> | <strong>merge</strong></p></blockquote><p>The ! negates the test, matching all possible results except the one specified. The case of the keywords is not significant.</p><p>The <em>STATUS</em> value is matched against the result of the lookup function called by the preceding service specification, and can be one of:</p><blockquote><dl><dt><strong>success</strong></dt><dd>No error occurred and the requested entry is returned. The default action for this condition is &quot;return&quot;.</dd><dt><strong>notfound</strong></dt><dd>The lookup succeeded, but the requested entry was not found. The default action for this condition is &quot;continue&quot;.</dd><dt><strong>unavail</strong></dt><dd>The service is permanently unavailable. This can mean either that the required file cannot be read, or, for network services, that the server is not available or does not allow queries. The default action for this condition is &quot;continue&quot;.</dd><dt><strong>tryagain</strong></dt><dd>The service is temporarily unavailable. This could mean a file is locked or a server currently cannot accept more connections. The default action for this condition is &quot;continue&quot;.</dd></dl></blockquote><p>The <em>ACTION</em> value can be one of:</p><blockquote><dl><dt><strong>return</strong></dt><dd>Return a result now. Do not call any further lookup functions. However, for compatibility reasons, if this is the selected action for the <strong>group</strong> database and the <strong>notfound</strong> status, and the configuration file does not contain the <strong>initgroups</strong> line, the next lookup function is always called, without affecting the search result.</dd><dt><strong>continue</strong></dt><dd>Call the next lookup function.</dd><dt><strong>merge</strong></dt><dd><em>[SUCCESS=merge]</em> is used between two database entries. When a group is located in the first of the two group entries, processing will continue on to the next one. If the group is also found in the next entry (and the group name and GID are an exact match), the member list of the second entry will be added to the group object to be returned. Available since glibc 2.24. Note that merging will not be done for <strong>getgrent</strong>(3) nor will duplicate members be pruned when they occur in both entries being merged.</dd></dl></blockquote><h3 id="compatibility-mode-compat" tabindex="-1">Compatibility mode (compat) <a class="header-anchor" href="#compatibility-mode-compat" aria-label="Permalink to &quot;Compatibility mode (compat)&quot;">​</a></h3><p>The NSS &quot;compat&quot; service is similar to &quot;files&quot; except that it additionally permits special entries in corresponding files for granting users or members of netgroups access to the system. The following entries are valid in this mode:</p><blockquote><p>For <strong>passwd</strong> and <strong>shadow</strong> databases:</p><blockquote><dl><dt><strong>+</strong> <em>user</em></dt><dd>Include the specified <em>user</em> from the NIS passwd/shadow map.</dd><dt><strong>+@</strong> <em>netgroup</em></dt><dd>Include all users in the given <em>netgroup</em>.</dd><dt><strong>-</strong> <em>user</em></dt><dd>Exclude the specified <em>user</em> from the NIS passwd/shadow map.</dd><dt><strong>-@</strong> <em>netgroup</em></dt><dd>Exclude all users in the given <em>netgroup</em>.</dd><dt><strong>+</strong></dt><dd>Include every user, except previously excluded ones, from the NIS passwd/shadow map.</dd></dl></blockquote><p>For <strong>group</strong> database:</p><blockquote><dl><dt><strong>+</strong> <em>group</em></dt><dd>Include the specified <em>group</em> from the NIS group map.</dd><dt><strong>-</strong> <em>group</em></dt><dd>Exclude the specified <em>group</em> from the NIS group map.</dd><dt><strong>+</strong></dt><dd>Include every group, except previously excluded ones, from the NIS group map.</dd></dl></blockquote></blockquote><p>By default, the source is &quot;nis&quot;, but this may be overridden by specifying any NSS service except &quot;compat&quot; itself as the source for the pseudo-databases <strong>passwd_compat</strong>, <strong>group_compat</strong>, and <strong>shadow_compat</strong>.</p><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><p>A service named <em>SERVICE</em> is implemented by a shared object library named <em>libnss_SERVICE.so.</em>* <em>X</em>* that resides in <em>/lib</em>.</p><blockquote><p><em>/etc/nsswitch.conf</em> NSS configuration file.</p><dl><dt><em>/lib/libnss_compat.so.</em>* <em>X</em>*</dt><dd>implements &quot;compat&quot; source.</dd><dt><em>/lib/libnss_db.so.</em>* <em>X</em>*</dt><dd>implements &quot;db&quot; source.</dd><dt><em>/lib/libnss_dns.so.</em>* <em>X</em>*</dt><dd>implements &quot;dns&quot; source.</dd><dt><em>/lib/libnss_files.so.</em>* <em>X</em>*</dt><dd>implements &quot;files&quot; source.</dd><dt><em>/lib/libnss_hesiod.so.</em>* <em>X</em>*</dt><dd>implements &quot;hesiod&quot; source.</dd><dt><em>/lib/libnss_nis.so.</em>* <em>X</em>*</dt><dd>implements &quot;nis&quot; source.</dd><dt><em>/lib/libnss_nisplus.so.</em>* <em>X</em>*</dt><dd>implements &quot;nisplus&quot; source.</dd></dl></blockquote><p>The following files are read when &quot;files&quot; source is specified for respective databases:</p><blockquote><p><strong>aliases</strong> <em>/etc/aliases</em></p><dl><dt><strong>ethers</strong></dt><dd><em>/etc/ethers</em></dd><dt><strong>group</strong></dt><dd><em>/etc/group</em></dd><dt><strong>hosts</strong></dt><dd><em>/etc/hosts</em></dd><dt><strong>initgroups</strong></dt><dd><em>/etc/group</em></dd><dt><strong>netgroup</strong></dt><dd><em>/etc/netgroup</em></dd><dt><strong>networks</strong></dt><dd><em>/etc/networks</em></dd><dt><strong>passwd</strong></dt><dd><em>/etc/passwd</em></dd><dt><strong>protocols</strong></dt><dd><em>/etc/protocols</em></dd><dt><strong>publickey</strong></dt><dd><em>/etc/publickey</em></dd><dt><strong>rpc</strong></dt><dd><em>/etc/rpc</em></dd><dt><strong>services</strong></dt><dd><em>/etc/services</em></dd><dt><strong>shadow</strong></dt><dd><em>/etc/shadow</em></dd></dl></blockquote><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>Starting with glibc 2.33, <strong>nsswitch.conf</strong> is automatically reloaded if the file is changed. In earlier versions, the entire file was read only once within each process. If the file was later changed, the process would continue using the old configuration.</p><p>Traditionally, there was only a single source for service information, often in the form of a single configuration file (e.g., <em>/etc/passwd</em>). However, as other name services, such as the Network Information Service (NIS) and the Domain Name Service (DNS), became popular, a method was needed that would be more flexible than fixed search orders coded into the C library. The Name Service Switch mechanism, which was based on the mechanism used by Sun Microsystems in the Solaris 2 C library, introduced a cleaner solution to the problem.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>getent</strong>(1), <strong>nss</strong>(5)</p>`,36))])}const b=s(d,[["render",c]]);export{f as __pageData,b as default};
